async () => {
      const opened = await toggleDevtools();
      if (opened === null) {
        // release 构建未启用 devtools feature，或运行在纯浏览器环境
        console.log(`[Dev] ${i18next.t('command_palette:notifications.dev_open_devtools_hint', 'Please press F12 to open DevTools in the browser')}`);
      }
    }

async () => {
      if (unifiedConfirm(i18next.t('command_palette:notifications.confirm_clear_cache', 'Are you sure you want to clear all cache data? This will reload the app.'))) {
        try {
          localStorage.clear();
          const databases = await indexedDB.databases();
          for (const db of databases) {
            if (db.name) {
              indexedDB.deleteDatabase(db.name);
            }
          }
          window.location.reload();
        } catch (e: unknown) {
          console.error(`[Dev] ${i18next.t('command_palette:notifications.dev_clear_cache_failed', 'Failed to clear cache')}`, e);
        }
      }
    }

async () => {
        try {
          // Tauri 全屏切换
          const { getCurrentWindow } = await import('@tauri-apps/api/window');
          const appWindow = getCurrentWindow();
          const isFullscreen = await appWindow.isFullscreen();
          await appWindow.setFullscreen(!isFullscreen);
        } catch {
          // Web fallback
          if (document.fullscreenElement) {
            document.exitFullscreen?.();
          } else {
            document.documentElement.requestFullscreen?.();
          }
        }
      }

async (deps) => {
        try {
          await copyTextToClipboard(window.location.href);
          deps.showNotification('success', i18next.t('command_palette:notifications.link_copied', 'Link copied'));
        } catch {
          deps.showNotification('error', i18next.t('command_palette:notifications.copy_failed', 'Copy failed'));
        }
      }

(deps) => {
      // 先获取当前状态，然后切换，通知显示切换后的状态
      const wasDark = deps.isDarkMode();
      deps.toggleTheme();
      // 切换后状态与之前相反
      deps.showNotification(
        'info',
        i18next.t(
          wasDark
            ? 'command_palette:notifications.theme_light'
            : 'command_palette:notifications.theme_dark'
        )
      );
    }

(deps) => {
      const currentLang = deps.getCurrentLanguage();
      const newLang = currentLang === 'zh-CN' ? 'en-US' : 'zh-CN';
      deps.switchLanguage(newLang);
      deps.showNotification(
        'info',
        i18next.t('command_palette:notifications.language_switched')
      );
    }

